package snippets.java.generics;

import java.util.*;
import java.util.function.*;

/**
 * Java Generics — Advanced Patterns
 */
public class AdvancedGenerics {

    // 1. Bounded wildcards
    public static double sumList(List<? extends Number> list) {
        return list.stream().mapToDouble(Number::doubleValue).sum();
    }
    public static void addNumbers(List<? super Integer> list, int count) {
        for (int i = 0; i < count; i++) list.add(i);
    }

    // 2. Generic methods
    public static <T extends Comparable<T>> T max(List<T> list) {
        return list.stream().max(Comparator.naturalOrder()).orElseThrow();
    }

    public static <A, B> List<B> mapList(List<A> list, Function<A, B> mapper) {
        List<B> result = new ArrayList<>(list.size());
        for (A item : list) result.add(mapper.apply(item));
        return result;
    }

    // 3. Generic pair
    record Pair<A, B>(A first, B second) {
        public Pair<B, A> swap() { return new Pair<>(second, first); }
        public <C> Pair<A, C> mapSecond(Function<B, C> fn) { return new Pair<>(first, fn.apply(second)); }
    }

    // 4. Generic stack
    static class Stack<T> {
        private final Deque<T> deque = new ArrayDeque<>();
        public void push(T item) { deque.push(item); }
        public T pop() { if (deque.isEmpty()) throw new EmptyStackException(); return deque.pop(); }
        public T peek() { return deque.peek(); }
        public boolean isEmpty() { return deque.isEmpty(); }
        public int size() { return deque.size(); }
    }

    // 5. Generic Result type
    sealed interface Result<T> permits Result.Success, Result.Failure {
        record Success<T>(T value) implements Result<T> {}
        record Failure<T>(Throwable cause) implements Result<T> {}

        static <T> Result<T> of(Supplier<T> supplier) {
            try { return new Success<>(supplier.get()); }
            catch (Throwable e) { return new Failure<>(e); }
        }

        default <U> Result<U> map(Function<T, U> fn) {
            return switch (this) {
                case Success<T> s -> Result.of(() -> fn.apply(s.value()));
                case Failure<T> f -> new Result.Failure<>(f.cause());
            };
        }

        default T orElse(T defaultValue) {
            return switch (this) {
                case Success<T> s -> s.value();
                case Failure<T> _ -> defaultValue;
            };
        }
    }

    // 6. Type-safe heterogeneous container (Bloch's pattern)
    static class TypeSafeMap {
        private final Map<Class<?>, Object> map = new HashMap<>();
        public <T> void put(Class<T> type, T instance) { map.put(Objects.requireNonNull(type), instance); }
        public <T> T get(Class<T> type) { return type.cast(map.get(type)); }
    }

    // 7. Recursive generics (Builder pattern)
    abstract static class AbstractBuilder<T, SELF extends AbstractBuilder<T, SELF>> {
        protected String name;
        @SuppressWarnings("unchecked")
        public SELF name(String n) { this.name = n; return (SELF) this; }
        public abstract T build();
    }
    static class PersonBuilder extends AbstractBuilder<String, PersonBuilder> {
        private int age;
        public PersonBuilder age(int a) { this.age = a; return this; }
        public String build() { return name + " (" + age + ")"; }
    }

    public static void main(String[] args) {
        // Wildcards
        System.out.println(sumList(List.of(1, 2.5, 3L))); // 6.5

        // Pair
        Pair<String, Integer> p = new Pair<>("Alice", 30);
        System.out.println(p.swap()); // Pair[first=30, second=Alice]
        System.out.println(p.mapSecond(age -> age + 1)); // Pair[first=Alice, second=31]

        // Result
        Result<Integer> r1 = Result.of(() -> Integer.parseInt("42"));
        Result<Integer> r2 = Result.of(() -> Integer.parseInt("abc"));
        System.out.println(r1.map(n -> n * 2).orElse(-1));  // 84
        System.out.println(r2.map(n -> n * 2).orElse(-1));  // -1

        // Builder
        String person = new PersonBuilder().name("Alice").age(30).build();
        System.out.println(person); // Alice (30)
    }
}

package snippets.java.db;

/**
 * Advanced SQL Patterns — used with JDBC/JPA
 */
public class AdvancedSQL {

    // All queries below are SQL strings used with JPA @Query or JDBC PreparedStatement

    // 1. Window Functions
    public static final String RANK_BY_DEPARTMENT = """
        SELECT name, department, salary,
               RANK()        OVER w AS rank_in_dept,
               DENSE_RANK()  OVER w AS dense_rank,
               ROW_NUMBER()  OVER w AS row_num,
               LAG(salary)   OVER w AS prev_salary,
               LEAD(salary)  OVER w AS next_salary,
               AVG(salary)   OVER (PARTITION BY department) AS dept_avg,
               SUM(salary)   OVER (PARTITION BY department ORDER BY salary
                                  ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_total
        FROM employees
        WINDOW w AS (PARTITION BY department ORDER BY salary DESC)
        ORDER BY department, rank_in_dept;
        """;

    // 2. CTE + Recursive
    public static final String EMPLOYEE_HIERARCHY = """
        WITH RECURSIVE hierarchy AS (
            SELECT id, name, manager_id, 0 AS depth
            FROM employees WHERE manager_id IS NULL
            UNION ALL
            SELECT e.id, e.name, e.manager_id, h.depth + 1
            FROM employees e JOIN hierarchy h ON e.manager_id = h.id
        )
        SELECT id, name, depth FROM hierarchy ORDER BY depth, name;
        """;

    // 3. UPSERT patterns
    public static final String UPSERT_POSTGRES = """
        INSERT INTO user_stats (user_id, login_count, last_login)
        VALUES (?, 1, NOW())
        ON CONFLICT (user_id)
        DO UPDATE SET
            login_count = user_stats.login_count + 1,
            last_login  = EXCLUDED.last_login;
        """;

    // 4. JSON operations (PostgreSQL)
    public static final String JSON_QUERY = """
        SELECT
            id,
            metadata->>'name' AS name,         -- text
            metadata->'address'->>'city' AS city,
            jsonb_array_length(metadata->'tags') AS tag_count
        FROM products
        WHERE metadata @> '{"active": true}'   -- JSON contains
          AND metadata->'price' < '100';
        """;

    // 5. Explain Analyze (for performance tuning)
    public static final String EXPLAIN_EXAMPLE = """
        EXPLAIN (ANALYZE, BUFFERS, FORMAT JSON)
        SELECT u.name, COUNT(o.id)
        FROM users u
        LEFT JOIN orders o ON u.id = o.user_id
        WHERE u.created_at > '2024-01-01'
        GROUP BY u.id
        HAVING COUNT(o.id) > 5;
        -- Look for: Seq Scan (bad on large table), high cost, index misses
        """;

    // 6. Materialized View (pre-compute heavy queries)
    public static final String CREATE_MATERIALIZED_VIEW = """
        CREATE MATERIALIZED VIEW daily_revenue AS
        SELECT
            DATE_TRUNC('day', created_at) AS day,
            SUM(amount) AS total_revenue,
            COUNT(*) AS order_count
        FROM orders
        WHERE status = 'completed'
        GROUP BY 1;

        CREATE UNIQUE INDEX ON daily_revenue (day);

        -- Refresh options:
        REFRESH MATERIALIZED VIEW CONCURRENTLY daily_revenue; -- no lock
        """;

    // 7. Partitioning by range
    public static final String PARTITION_TABLE = """
        CREATE TABLE events (
            id         BIGSERIAL,
            created_at TIMESTAMP NOT NULL,
            payload    JSONB
        ) PARTITION BY RANGE (created_at);

        CREATE TABLE events_2024_q1 PARTITION OF events
            FOR VALUES FROM ('2024-01-01') TO ('2024-04-01');

        CREATE TABLE events_2024_q2 PARTITION OF events
            FOR VALUES FROM ('2024-04-01') TO ('2024-07-01');
        -- Queries automatically routed to correct partition
        """;

    public static void main(String[] args) {
        // These queries would be executed via JPA @Query or JDBC
        System.out.println("SQL patterns library loaded");
        System.out.println("Queries available: Window, CTE, Upsert, JSON, Explain, MatView, Partition");
    }
}

package snippets.java.concurrent;

import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import java.util.concurrent.locks.*;

/**
 * Advanced Java Concurrency Patterns
 */
public class AdvancedConcurrency {

    // 1. ReadWriteLock — multiple readers OR one writer
    static class ReadWriteCache<K, V> {
        private final ConcurrentHashMap<K, V> map = new ConcurrentHashMap<>();
        private final ReadWriteLock lock = new ReentrantReadWriteLock();
        private final Lock readLock  = lock.readLock();
        private final Lock writeLock = lock.writeLock();

        public V get(K key) {
            readLock.lock();
            try { return map.get(key); }
            finally { readLock.unlock(); }
        }

        public void put(K key, V value) {
            writeLock.lock();
            try { map.put(key, value); }
            finally { writeLock.unlock(); }
        }
    }

    // 2. StampedLock — optimistic reads (Java 8+)
    static class StampedCache {
        private final StampedLock lock = new StampedLock();
        private double value = 0;

        public double read() {
            long stamp = lock.tryOptimisticRead();  // no lock!
            double v = value;
            if (!lock.validate(stamp)) {            // check no write happened
                stamp = lock.readLock();
                try { v = value; }
                finally { lock.unlockRead(stamp); }
            }
            return v;
        }

        public void write(double newValue) {
            long stamp = lock.writeLock();
            try { value = newValue; } finally { lock.unlockWrite(stamp); }
        }
    }

    // 3. Atomic operations
    static class AtomicCounter {
        private final AtomicLong counter = new AtomicLong(0);
        private final AtomicReference<String> state = new AtomicReference<>("IDLE");

        public long increment() { return counter.incrementAndGet(); }
        public long addAndGet(long delta) { return counter.addAndGet(delta); }

        // CAS — Compare-And-Swap
        public boolean transitionState(String expected, String next) {
            return state.compareAndSet(expected, next);
        }

        // getAndUpdate with lambda
        public long updateConditionally(long minVal) {
            return counter.updateAndGet(v -> Math.max(v, minVal));
        }
    }

    // 4. Phaser (flexible synchronization barrier)
    static void phaserExample() throws InterruptedException {
        Phaser phaser = new Phaser(3); // 3 parties
        for (int i = 0; i < 3; i++) {
            final int id = i;
            new Thread(() -> {
                System.out.println(id + " preparing, phase " + phaser.getPhase());
                phaser.arriveAndAwaitAdvance();  // wait for all
                System.out.println(id + " executing, phase " + phaser.getPhase());
                phaser.arriveAndAwaitAdvance();  // wait for all again
                System.out.println(id + " done");
                phaser.arriveAndDeregister();    // deregister
            }).start();
        }
    }

    // 5. BlockingQueue patterns (producer-consumer)
    static class PipelineStage<T> {
        private final BlockingQueue<T> queue = new LinkedBlockingQueue<>(100);

        public void produce(T item) throws InterruptedException {
            queue.put(item); // blocks if full
        }

        public T consume() throws InterruptedException {
            return queue.take(); // blocks if empty
        }

        public T pollWithTimeout(long ms) throws InterruptedException {
            return queue.poll(ms, TimeUnit.MILLISECONDS);
        }
    }

    // 6. CompletableFuture orchestration
    static CompletableFuture<String> callServiceA() { return CompletableFuture.supplyAsync(() -> "A"); }
    static CompletableFuture<String> callServiceB() { return CompletableFuture.supplyAsync(() -> "B"); }
    static CompletableFuture<String> callServiceC(String aResult) { return CompletableFuture.supplyAsync(() -> aResult + "-C"); }

    static void orchestrate() {
        // A and B in parallel, then C depends on A, then combine all
        CompletableFuture<String> aFuture = callServiceA();
        CompletableFuture<String> bFuture = callServiceB();
        CompletableFuture<String> cFuture = aFuture.thenCompose(AdvancedConcurrency::callServiceC);

        CompletableFuture.allOf(aFuture, bFuture, cFuture).thenRun(() -> {
            String a = aFuture.join(), b = bFuture.join(), c = cFuture.join();
            System.out.println(a + " | " + b + " | " + c); // A | B | A-C
        }).join();
    }

    public static void main(String[] args) throws Exception {
        AtomicCounter counter = new AtomicCounter();
        System.out.println(counter.increment()); // 1
        System.out.println(counter.transitionState("IDLE", "RUNNING")); // true
        orchestrate();
    }
}

package snippets.java.patterns;

import java.util.*;
import java.util.function.*;

/**
 * Behavioral Design Patterns in Java
 */
public class BehavioralPatterns {

    // ---- 1. Observer Pattern ----
    interface EventListener<T> { void onEvent(T event); }

    static class EventBus<T> {
        private final Map<String, List<EventListener<T>>> listeners = new HashMap<>();
        public void subscribe(String event, EventListener<T> listener) {
            listeners.computeIfAbsent(event, k -> new ArrayList<>()).add(listener);
        }
        public void publish(String event, T data) {
            listeners.getOrDefault(event, List.of()).forEach(l -> l.onEvent(data));
        }
    }

    // ---- 2. Strategy Pattern ----
    interface SortStrategy { void sort(int[] arr); }

    static class Sorter {
        private SortStrategy strategy;
        Sorter(SortStrategy s) { this.strategy = s; }
        void setStrategy(SortStrategy s) { this.strategy = s; }
        void sort(int[] arr) { strategy.sort(arr); }
    }

    // ---- 3. Command Pattern ----
    interface Command { void execute(); void undo(); }

    static class TextEditor {
        private StringBuilder text = new StringBuilder();
        private final Deque<Command> history = new ArrayDeque<>();

        public void executeCommand(Command cmd) { cmd.execute(); history.push(cmd); }
        public void undo() { if (!history.isEmpty()) history.pop().undo(); }
        public String getText() { return text.toString(); }

        class InsertCommand implements Command {
            private final String toInsert; private final int pos;
            InsertCommand(String s, int p) { toInsert=s; pos=p; }
            public void execute() { text.insert(pos, toInsert); }
            public void undo() { text.delete(pos, pos + toInsert.length()); }
        }
    }

    // ---- 4. Chain of Responsibility ----
    abstract static class Handler {
        protected Handler next;
        Handler setNext(Handler h) { this.next = h; return h; }
        abstract boolean handle(int request);
    }

    static class AuthHandler extends Handler {
        public boolean handle(int req) {
            if (req < 1) { System.out.println("Auth failed"); return false; }
            return next == null || next.handle(req);
        }
    }
    static class RateLimitHandler extends Handler {
        public boolean handle(int req) {
            if (req > 1000) { System.out.println("Rate limit exceeded"); return false; }
            return next == null || next.handle(req);
        }
    }
    static class BusinessHandler extends Handler {
        public boolean handle(int req) { System.out.println("Processing: " + req); return true; }
    }

    // ---- 5. Template Method ----
    abstract static class DataProcessor {
        // Template method defines algorithm skeleton
        public final void process() {
            readData();      // step 1
            processData();   // step 2 — abstract, subclass defines
            writeResults();  // step 3
        }
        protected void readData() { System.out.println("Reading data"); }
        protected abstract void processData();
        protected void writeResults() { System.out.println("Writing results"); }
    }

    static class CsvProcessor extends DataProcessor {
        protected void processData() { System.out.println("Processing CSV"); }
    }

    // ---- 6. State Pattern ----
    interface OrderState { void next(OrderContext ctx); String status(); }
    static class OrderContext {
        private OrderState state = new PendingState();
        public void setState(OrderState s) { this.state = s; }
        public void next() { state.next(this); }
        public String getStatus() { return state.status(); }
    }
    static class PendingState  implements OrderState { public void next(OrderContext c){c.setState(new ProcessingState());} public String status(){return "PENDING";} }
    static class ProcessingState implements OrderState { public void next(OrderContext c){c.setState(new ShippedState());} public String status(){return "PROCESSING";} }
    static class ShippedState   implements OrderState { public void next(OrderContext c){c.setState(new DeliveredState());} public String status(){return "SHIPPED";} }
    static class DeliveredState implements OrderState { public void next(OrderContext c){} public String status(){return "DELIVERED";} }

    public static void main(String[] args) {
        // Observer
        EventBus<String> bus = new EventBus<>();
        bus.subscribe("login", e -> System.out.println("User logged in: " + e));
        bus.publish("login", "Alice");

        // Chain of Responsibility
        Handler auth = new AuthHandler();
        auth.setNext(new RateLimitHandler()).setNext(new BusinessHandler());
        auth.handle(42);   // processes
        auth.handle(-1);   // auth fails

        // State
        OrderContext order = new OrderContext();
        System.out.println(order.getStatus()); // PENDING
        order.next(); System.out.println(order.getStatus()); // PROCESSING
        order.next(); System.out.println(order.getStatus()); // SHIPPED

        // Template method
        new CsvProcessor().process();
    }
}
